values
  ('6bae1008-dd78-488b-a690-1cfabdb41fe9', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Fieldwork Foundations and the Anthropological Field', 'This section frames fieldwork as a disciplined way of learning from places, people, materials, institutions, and everyday practice while recognizing that the field is produced through relationships and power.', 0),
  ('f452b711-8c56-448a-ba9a-995c987b639c', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '6bae1008-dd78-488b-a690-1cfabdb41fe9', 'subtopic'::public.curated_course_node_type, 'What counts as the field', 'Students learn that the field may be a village, archive, clinic, dig site, museum, workplace, digital space, or multi-sited network.', 0),
  ('192be086-8534-4044-a959-4aa6b7d3938d', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'f452b711-8c56-448a-ba9a-995c987b639c', 'concept'::public.curated_course_node_type, 'Ethnographic, archaeological, biological, and applied field settings', null, 0),
