  ('9d1bfdf4-0346-4835-ac15-35e60933c6df', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd4980c82-d01a-4ac2-92d9-d4b31f07bc67', 'concept'::public.curated_course_node_type, 'Descriptive, comparative, and explanatory questions', null, 0),
  ('4d26164f-a767-4a4b-8f8b-8e9a9b93c8e8', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd4980c82-d01a-4ac2-92d9-d4b31f07bc67', 'concept'::public.curated_course_node_type, 'Researchable scope and field constraints', null, 1),
