  ('8e12c40c-4a27-41d5-9992-8ad31e741327', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'a8c4cb64-8758-4e2a-b936-e8b71c5e54d8', 'concept'::public.curated_course_node_type, 'Preparedness and punctuality', null, 0),
  ('e95ee13a-cea7-43e4-9689-6a64e07b5ca0', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'a8c4cb64-8758-4e2a-b936-e8b71c5e54d8', 'concept'::public.curated_course_node_type, 'Careful observation and humility', null, 1),
  ('dd8f0300-d074-4bd7-a4e2-7136815e0be6', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'a8c4cb64-8758-4e2a-b936-e8b71c5e54d8', 'concept'::public.curated_course_node_type, 'Accountability to teams, sites, and communities', null, 2),
  ('0b1198b9-2f3e-4867-9e7a-a177ec5fe4e5', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Research Design and Field Preparation', 'Strong fieldwork begins before arrival. This section teaches students to prepare research questions, logistics, permissions, equipment, and field protocols.', 1),
