  ('a476cf46-df29-4b1d-9c1a-c3bc1c2629b3', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2ff50048-1633-4123-beec-86d2521c02cd', 'concept'::public.curated_course_node_type, 'Research aims and scope', null, 0),
  ('fcefd597-2d91-4948-afae-10480fe695f4', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2ff50048-1633-4123-beec-86d2521c02cd', 'concept'::public.curated_course_node_type, 'Method selection and sequencing', null, 1),
  ('c8731180-0a78-4864-b40c-71c128511693', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2ff50048-1633-4123-beec-86d2521c02cd', 'concept'::public.curated_course_node_type, 'Feasible timeline and milestones', null, 2),
  ('04f4349d-75e7-4b3f-b2c4-0756e36e773f', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '0b1198b9-2f3e-4867-9e7a-a177ec5fe4e5', 'subtopic'::public.curated_course_node_type, 'Logistics and readiness', 'The gist is that practical preparation protects both research quality and participant safety.', 1),
  ('8426278e-8738-4220-a142-5deba4fe31ec', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '04f4349d-75e7-4b3f-b2c4-0756e36e773f', 'concept'::public.curated_course_node_type, 'Travel, housing, equipment, and supplies', null, 0),
  ('69e2ad94-227f-4769-b750-c57594a4b02a', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '04f4349d-75e7-4b3f-b2c4-0756e36e773f', 'concept'::public.curated_course_node_type, 'Contact lists and contingency plans', null, 1),
  ('e917aa5b-18e8-4afd-899a-13193205aa48', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '04f4349d-75e7-4b3f-b2c4-0756e36e773f', 'concept'::public.curated_course_node_type, 'Budgeting and procurement basics', null, 2),
