  ('f0707dbb-d65a-4a31-bb08-076a3f5f4b67', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '886645f7-30e3-4a4a-bc64-c373726fe534', 'concept'::public.curated_course_node_type, 'Interview and survey instruments', null, 1),
  ('8e08a814-de88-4b98-a7f1-36524ddfd069', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '886645f7-30e3-4a4a-bc64-c373726fe534', 'concept'::public.curated_course_node_type, 'Recording, backup, and daily debrief routines', null, 2),
