  ('3fc2abd5-2d7f-49e9-b6c4-c78496150bfb', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '28eb9bb4-af56-4f43-ae10-e97f644e5389', 'concept'::public.curated_course_node_type, 'Archaeological permits and site permissions', null, 0),
  ('7edbd2e2-3924-4f14-a440-9789b211f862', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '28eb9bb4-af56-4f43-ae10-e97f644e5389', 'concept'::public.curated_course_node_type, 'Agency, school, clinic, or organizational access', null, 1),
  ('955b2d6f-b869-44ef-a85c-79c61293dc0f', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '28eb9bb4-af56-4f43-ae10-e97f644e5389', 'concept'::public.curated_course_node_type, 'Export, collections, and documentation restrictions', null, 2),
