  ('dfb95299-4edd-4747-bcb5-884e0139a29e', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'f61e62e6-d579-4cbe-828c-66b93d780307', 'concept'::public.curated_course_node_type, 'Human subjects definitions', null, 0),
  ('5d095500-7216-4a07-a00a-17dd1ee41e28', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'f61e62e6-d579-4cbe-828c-66b93d780307', 'concept'::public.curated_course_node_type, 'Exempt, expedited, and full-review logics', null, 1),
