  ('7549e633-4dd1-4860-80f9-f70e4635ad76', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '83a04963-6d46-4a54-9371-61a00db310dd', 'concept'::public.curated_course_node_type, 'Initial contact and introduction letters', null, 0),
  ('117afa0c-a843-45b9-b0d4-2c383a7c0d1b', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '83a04963-6d46-4a54-9371-61a00db310dd', 'concept'::public.curated_course_node_type, 'Community liaisons and local collaborators', null, 1),
  ('abb8ac03-3e5b-4ac3-993c-85503af40379', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '83a04963-6d46-4a54-9371-61a00db310dd', 'concept'::public.curated_course_node_type, 'Maintaining access through trust', null, 2),
  ('77dfcebf-df4e-4fa5-968c-3a52f422f78c', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Safety, Risk Management, and Field Logistics', 'A field course treats safety as a research competency, not an afterthought.', 3);
