  ('38eddb75-5923-4a71-9a1f-2a2eea42d28c', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd331e561-4081-428a-80bb-dc4cd4404f13', 'concept'::public.curated_course_node_type, 'Incident logs and near-miss reporting', null, 1),
  ('43c05662-ec44-4d69-876a-731ffdb820fd', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd331e561-4081-428a-80bb-dc4cd4404f13', 'concept'::public.curated_course_node_type, 'Insurance, medical, and emergency records', null, 2),
