  ('737fd86d-ccb1-4a8d-aac1-6f3716380cb1', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '6930d831-2ce2-4361-85c2-80c20f4d4945', 'concept'::public.curated_course_node_type, 'Environmental and built features', null, 0),
