  ('69ff107a-ba59-42ae-be6e-18855f552f9b', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '6930d831-2ce2-4361-85c2-80c20f4d4945', 'concept'::public.curated_course_node_type, 'Contextual sketches and photo logs', null, 2),
