  ('aa0abe11-8753-4087-89ea-e8172770a605', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'cc4c9aaa-5534-4207-9f33-ea5de57a9252', 'concept'::public.curated_course_node_type, 'Settlement, land use, and infrastructure', null, 1),
  ('0a8ddd94-0db4-4854-a811-6b5c1b8de6bb', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'cc4c9aaa-5534-4207-9f33-ea5de57a9252', 'concept'::public.curated_course_node_type, 'Sacred, contested, or sensitive places', null, 2),
  ('2fc59d06-5138-4263-89ed-50b0eabf20db', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Systematic Observation and Participant Observation', 'Observation is a method, not merely looking around. Students learn how to notice patterns while remaining reflexive about their own position.', 5),
  ('2c3bf1aa-d55e-4213-b258-34cf173455a3', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2fc59d06-5138-4263-89ed-50b0eabf20db', 'subtopic'::public.curated_course_node_type, 'Observation strategies', 'Students practice moving from open noticing to structured recording.', 0),
  ('96bbbd32-b0a4-4037-bc0e-53117d093d6a', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2c3bf1aa-d55e-4213-b258-34cf173455a3', 'concept'::public.curated_course_node_type, 'Descriptive observation', null, 0),
  ('640f4673-227e-43d6-b886-13a75389d043', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2c3bf1aa-d55e-4213-b258-34cf173455a3', 'concept'::public.curated_course_node_type, 'Focused observation', null, 1),
  ('870949a4-183c-4b56-97a1-ce06dbff151d', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2c3bf1aa-d55e-4213-b258-34cf173455a3', 'concept'::public.curated_course_node_type, 'Time allocation and event sampling', null, 2),
  ('dd2d1c80-92bc-43ea-b9de-1954605f540d', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2fc59d06-5138-4263-89ed-50b0eabf20db', 'subtopic'::public.curated_course_node_type, 'Participation and rapport', 'The gist is that participation can deepen understanding when handled respectfully.', 1),
  ('6f520b36-073a-40db-8682-8a28cf77e83b', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'dd2d1c80-92bc-43ea-b9de-1954605f540d', 'concept'::public.curated_course_node_type, 'Roles in the field', null, 0),
  ('c76cc16a-bce1-4c3f-903a-9359f557839e', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'dd2d1c80-92bc-43ea-b9de-1954605f540d', 'concept'::public.curated_course_node_type, 'Rapport, reciprocity, and boundaries', null, 1),
  ('6a5a4f74-44e0-4b3f-8b92-c2d340e6f279', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'dd2d1c80-92bc-43ea-b9de-1954605f540d', 'concept'::public.curated_course_node_type, 'Observer effects and positionality', null, 2),
  ('1b829d1f-a38c-4897-adc4-2d8b455bec3c', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2fc59d06-5138-4263-89ed-50b0eabf20db', 'subtopic'::public.curated_course_node_type, 'Analytic noticing', 'Students learn to distinguish detail, pattern, interpretation, and assumption.', 2),
  ('28712ea0-94eb-49aa-b476-15648403e3ef', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '1b829d1f-a38c-4897-adc4-2d8b455bec3c', 'concept'::public.curated_course_node_type, 'Routines and exceptions', null, 0),
  ('947e78fc-8679-43ca-bf68-afee167a4293', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '1b829d1f-a38c-4897-adc4-2d8b455bec3c', 'concept'::public.curated_course_node_type, 'Embodied practice and tacit knowledge', null, 1),
  ('2231e628-d147-4ca7-ac56-a3d9edbf321a', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '1b829d1f-a38c-4897-adc4-2d8b455bec3c', 'concept'::public.curated_course_node_type, 'Material, spatial, and interactional cues', null, 2),
  ('f451876e-6538-4d25-9ad8-3467bbcd87b2', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Interviewing, Oral Histories, and Survey Practice', 'Field schools should train students to ask good questions, listen carefully, document responsibly, and understand the limits of self-reported data.', 6),
  ('7b5d4c79-77af-4b81-8345-54fcdda219c2', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'f451876e-6538-4d25-9ad8-3467bbcd87b2', 'subtopic'::public.curated_course_node_type, 'Interview design', 'Students learn how question design shapes what can be learned.', 0);
