  ('5cf8f461-2374-449e-b6aa-1933bb322196', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '2b8a01ee-2514-406d-848e-64b7353f8884', 'concept'::public.curated_course_node_type, 'Narrative context and interpretation', null, 2),
  ('9384353d-047f-4b8d-8dc6-21830395c506', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'f451876e-6538-4d25-9ad8-3467bbcd87b2', 'subtopic'::public.curated_course_node_type, 'Surveys and short instruments', 'Students learn when structured instruments are useful and when they flatten complexity.', 2),
  ('926fa933-390a-48da-a916-a95f38cbec15', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '9384353d-047f-4b8d-8dc6-21830395c506', 'concept'::public.curated_course_node_type, 'Question wording and response options', null, 0),
  ('03d2837e-575a-435e-84ae-0d98e2f18826', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '9384353d-047f-4b8d-8dc6-21830395c506', 'concept'::public.curated_course_node_type, 'Sampling and recruitment', null, 1),
  ('f0965d21-ea6c-4c2d-9932-231ae0fcd4c8', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '9384353d-047f-4b8d-8dc6-21830395c506', 'concept'::public.curated_course_node_type, 'Pilot testing and revision', null, 2),
  ('d6ddda4b-0411-43b7-b3ed-46690b13a104', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', null, 'topic'::public.curated_course_node_type, 'Excavation, Survey, and Material Culture Techniques', 'For archaeology-centered field schools, students need hands-on training in survey, excavation, context recording, and material interpretation.', 7),
  ('adb9c3a6-ce82-4c1d-b224-3f2c2e8b68e7', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd6ddda4b-0411-43b7-b3ed-46690b13a104', 'subtopic'::public.curated_course_node_type, 'Archaeological survey', 'Students learn how archaeologists identify, record, and interpret surface evidence.', 0),
  ('50262d0e-6c4b-4176-b2f1-79745547d8bc', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'adb9c3a6-ce82-4c1d-b224-3f2c2e8b68e7', 'concept'::public.curated_course_node_type, 'Pedestrian survey and transects', null, 0),
  ('fc7e498d-f546-4b23-8407-8ca5c9fea216', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'adb9c3a6-ce82-4c1d-b224-3f2c2e8b68e7', 'concept'::public.curated_course_node_type, 'Site forms and artifact scatters', null, 1),
  ('4204afb3-0483-4a72-b965-5bf41a36062e', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'adb9c3a6-ce82-4c1d-b224-3f2c2e8b68e7', 'concept'::public.curated_course_node_type, 'Remote sensing and non-invasive approaches', null, 2),
  ('8387e6ca-19d0-4a39-bb96-795b63ad39b6', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd6ddda4b-0411-43b7-b3ed-46690b13a104', 'subtopic'::public.curated_course_node_type, 'Excavation practice', 'The point is to recover information without destroying context unnecessarily.', 1),
  ('3e2c4393-46ef-411a-b3fd-14190bede9fe', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8387e6ca-19d0-4a39-bb96-795b63ad39b6', 'concept'::public.curated_course_node_type, 'Stratigraphy and provenience', null, 0),
  ('d345f7c4-b4ce-4c19-a21b-8ac83cfc9aa8', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8387e6ca-19d0-4a39-bb96-795b63ad39b6', 'concept'::public.curated_course_node_type, 'Unit setup and levels', null, 1),
  ('4ec1cbd7-072d-451a-a20e-1341cf7912bc', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8387e6ca-19d0-4a39-bb96-795b63ad39b6', 'concept'::public.curated_course_node_type, 'Screening, sampling, and feature recording', null, 2),
  ('8d64c427-3764-4b95-8116-ab5a48c3da91', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'd6ddda4b-0411-43b7-b3ed-46690b13a104', 'subtopic'::public.curated_course_node_type, 'Material culture interpretation', 'Students learn that artifacts matter through context, use, deposition, and relationships.', 2),
  ('615329e9-6793-40c1-a399-52062319339e', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8d64c427-3764-4b95-8116-ab5a48c3da91', 'concept'::public.curated_course_node_type, 'Classification and typology', null, 0),
  ('83637a0b-5e5e-4ef0-a2f8-0bd5dc337ff0', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8d64c427-3764-4b95-8116-ab5a48c3da91', 'concept'::public.curated_course_node_type, 'Use-wear and function', null, 1),
  ('ca9ee782-175c-4a13-9146-1ec550903212', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '8d64c427-3764-4b95-8116-ab5a48c3da91', 'concept'::public.curated_course_node_type, 'Contextual and comparative interpretation', null, 2),
