  ('bcd821ac-1852-4810-81e3-3dc24868fd49', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '7a6740c2-0aab-47c6-a134-13946e4b86a8', 'concept'::public.curated_course_node_type, 'Co-designed questions', null, 0),
  ('786c820f-d210-4f7e-b423-94a1140c7641', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '7a6740c2-0aab-47c6-a134-13946e4b86a8', 'concept'::public.curated_course_node_type, 'Shared field roles', null, 1),
  ('841b14fe-bba0-4a93-bf62-278f34363ade', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '7a6740c2-0aab-47c6-a134-13946e4b86a8', 'concept'::public.curated_course_node_type, 'Community review of plans and findings', null, 2),
  ('0ce5daca-a167-4914-a9a0-fae60c567710', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '469d73f1-3e4e-4086-a303-b295d8f535d8', 'subtopic'::public.curated_course_node_type, 'Participatory methods', 'The gist is to generate knowledge with people rather than only about them.', 1),
  ('5e06b394-a47e-44c7-80fc-04dcbb0bab5c', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '0ce5daca-a167-4914-a9a0-fae60c567710', 'concept'::public.curated_course_node_type, 'Participatory mapping', null, 0),
