  ('6e7a08ca-d74a-4a09-84b6-030f6d3b6e89', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'e88b51a4-684f-4943-8a5d-1d92209447ff', 'concept'::public.curated_course_node_type, 'Return of findings', null, 0),
  ('dea0fbe2-f1ec-4c4e-956c-5041752a0c0d', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', 'e88b51a4-684f-4943-8a5d-1d92209447ff', 'concept'::public.curated_course_node_type, 'Accessible outputs', null, 1),
