  ('698fecdb-4cce-46ca-954a-ec95a472d463', 'd2e3f4a5-6b7c-4e12-9f12-2a3b4c5d6e22', '329f9d07-2bd9-4b46-a224-fea3d9c375c6', 'subtopic'::public.curated_course_node_type, 'Cataloging systems', 'Students learn to assign consistent identifiers and metadata.', 0),
